  "codebook": {
    "definition": "Credit-claiming is defined as any public statement by a senator acting to generate the belief among constituents or key actors that they are personally or jointly responsible for causing the government, or some desirable entity, to do something that is considered beneficial.",
    "clarification": "To qualify as credit-claiming, the senator must claim personal or joint responsibility (e.g., through a delegation) for an accomplished positive outcome. This includes: (a) securing federal funding, grants, or projects for their home state; (b) successfully passing legislation, amendments, or resolutions they sponsored or co-sponsored; (c) successfully executing constituent service or regulatory interventions (e.g., resolving bureaucratic red tape, securing disaster declarations); or (d) securing specific committee approvals or policy concessions. Merely announcing a grant is also included as credit-claiming if the senator associates themselves with the funding delivery or notes their ongoing advocacy for the program.",
    "positive_examples": [
      {
        "document_id": "1862",
        "explanation": "The senators explicitly claim that they 'have delivered on their promise to secure federal funding' of $12.5 million for military projects in Butte, Montana."
      },
      {
        "document_id": "3201",
        "explanation": "Senator Talent explicitly claims credit for working with USDA officials to expedite the approval of Missouri's agricultural disaster designation, bringing immediate aid eligibility to local farmers."
      },
      {
        "document_id": "1060",
        "explanation": "Senator Nelson highlights that a major piece of healthcare legislation passed by Congress 'also includes an amendment co-sponsored by Senator Nelson,' taking responsibility for a specific policy addition."
      }
    ],
    "negative_clarification": "A text should NOT be classified as credit-claiming if the senator: (a) merely introduces, sponsors, or co-sponsors a bill that has not yet passed; (b) explains their vote on a bill without claiming responsibility for its specific design or passage; (c) issues a statement that solely criticizes opponents or the administration without claiming a personal policy achievement; (d) welcomes a government decision or agency action without claiming a personal causal role in achieving it; or (e) releases purely symbolic or memorial statements, such as holiday greetings or condolences.",
    "negative_examples": [
      {
